/* ═══ Modelo de reinos que escogió el docente (BIO_CLASIF en bio.js) ═══
   m:'5' = solo con 5 reinos; m:'6', m:'7' o m:'67' = solo con ese modelo;
   d:1 = solo si se trabajan los 3 dominios. Las preguntas que nombran el
   modelo («en el modelo de cinco reinos», Whittaker, Woese) sirven en todos. */
(function(){
var B=window.BANCO_BIO;if(!B)return;
var SOLO5=['Las bacterias y las cianobacterias pertenecen al reino:','La ameba y el paramecio pertenecen al reino:','¿Qué organismo pertenece al reino Monera?'];
var SOLO56=['Las algas verdes, rojas y pardas se clasifican tradicionalmente en el reino:'];
var DOM=['¿Quién propuso los tres dominios (Bacteria, Archaea y Eukarya)?','Los seres vivos con núcleo pertenecen al dominio:'];
B.forEach(function(q){if(q.t!=='reinos')return;if(SOLO5.indexOf(q.q)>=0)q.m='5';if(SOLO56.indexOf(q.q)>=0)q.m='56';if(DOM.indexOf(q.q)>=0)q.d=1;});
function mc(m,q,ops,a,exp,p,d){var o={t:'reinos',k:'mc',m:m,q:q,ops:ops,a:a,exp:exp,p:p};if(d)o.d=1;B.push(o);}
mc('6','Las bacterias del yogur y las cianobacterias pertenecen al reino:',['Eubacteria','Archaebacteria','Protista','Plantae'],0,'En el modelo de seis reinos, las procariotas con pared de peptidoglucano, como los lactobacilos del yogur y las cianobacterias, forman el reino Eubacteria.',['No tienen núcleo.','Su pared tiene peptidoglucano, la que ataca la penicilina.']);
mc('7','Las bacterias del yogur y las cianobacterias pertenecen al reino:',['Bacteria','Archaea','Chromista','Plantae'],0,'En el modelo de siete reinos, las procariotas con pared de peptidoglucano forman el reino Bacteria. Las cianobacterias hacen fotosíntesis, pero no son plantas.',['No tienen núcleo.','Su pared tiene peptidoglucano.']);
mc('6','Las arqueas de las salinas de Manaure pertenecen al reino:',['Archaebacteria','Eubacteria','Protista','Fungi'],0,'En el modelo de seis reinos, las arqueas forman el reino Archaebacteria: procariotas sin peptidoglucano y con membranas de enlaces éter que resisten la sal.',['No tienen núcleo, pero no son bacterias verdaderas.','Su nombre empieza por «Archae».']);
mc('7','Las arqueas de las salinas de Manaure pertenecen al reino:',['Archaea','Bacteria','Protozoa','Fungi'],0,'En el modelo de siete reinos, las arqueas forman el reino Archaea: procariotas sin peptidoglucano y con membranas de enlaces éter.',['No tienen núcleo, pero no son bacterias.','Viven en lugares extremos, como las salinas.']);
mc('6','La ameba y el paramecio pertenecen al reino:',['Protista','Eubacteria','Fungi','Animalia'],0,'En el modelo de seis reinos, los eucariotas sencillos como la ameba y el paramecio siguen en el reino Protista.',['Tienen núcleo, pero son de una sola célula.','No son hongos, plantas ni animales.']);
mc('7','La ameba, que se mueve con seudópodos, pertenece al reino:',['Protozoa','Chromista','Bacteria','Animalia'],0,'En el modelo de siete reinos, la ameba es del reino Protozoa, junto con las euglenas y el tripanosoma del Chagas.',['Es eucariota y casi siempre unicelular.','En este modelo el antiguo reino Protista se partió en dos.']);
mc('7','El paramecio, el plasmodio de la malaria y las diatomeas pertenecen al reino:',['Chromista','Protozoa','Fungi','Plantae'],0,'En el modelo de siete reinos, el paramecio, el plasmodio y las diatomeas quedan en Chromista: su línea evolutiva ganó cloroplastos al tragarse un alga roja.',['Es uno de los dos reinos en que se partió Protista.','También incluye las algas pardas, como el sargazo.']);
mc('7','El tripanosoma que causa la enfermedad de Chagas pertenece al reino:',['Protozoa','Chromista','Bacteria','Animalia'],0,'El tripanosoma es un eucariota unicelular con flagelo: en el modelo de siete reinos va en Protozoa, junto con las amebas y las euglenas.',['Es una sola célula con núcleo y flagelo.','Va con las amebas.']);
mc('7','Las algas pardas, como el sargazo del Caribe, pertenecen al reino:',['Chromista','Plantae','Protozoa','Fungi'],0,'En el modelo de siete reinos, las algas pardas son Chromista, no plantas: tienen otra clase de cloroplastos y otra historia evolutiva.',['No son plantas, aunque hagan fotosíntesis.','Comparten reino con las diatomeas.']);
mc('6','¿Qué organismo pertenece al reino Eubacteria?',['Escherichia coli (bacteria del intestino)','Arquea de las salinas de Manaure','Ameba de los charcos y quebradas','Levadura que se usa para el pan'],0,'Escherichia coli es una procariota con pared de peptidoglucano: una eubacteria. Las arqueas forman otro reino en el modelo de seis reinos.',['No tiene núcleo.','Vive en tu intestino.']);
mc('7','¿Qué organismo pertenece al reino Bacteria?',['Escherichia coli (bacteria del intestino)','Arquea de las salinas de Manaure','Paramecio de los charcos y quebradas','Levadura que se usa para el pan'],0,'Escherichia coli es una procariota con pared de peptidoglucano: del reino Bacteria. Las arqueas forman el reino Archaea.',['No tiene núcleo.','Vive en tu intestino.']);
mc('67','¿Qué diferencia de pared separa a las eubacterias de las arqueas?',['Solo las eubacterias tienen peptidoglucano','Solo las arqueas tienen pared','Las arqueas tienen celulosa','Las eubacterias tienen quitina'],0,'La pared de las eubacterias tiene peptidoglucano; la de las arqueas no. Por eso la penicilina ataca a las eubacterias y no a las arqueas.',['La penicilina ataca esta sustancia.','Las arqueas no la tienen.']);
mc('7','¿En cuántos reinos parte el reino Protista el modelo de siete reinos?',['En dos: Protozoa y Chromista','En tres','No lo parte','En dos: Fungi y Plantae'],0,'El modelo de siete reinos (Ruggiero y otros, 2015) divide Protista en Protozoa y Chromista, según su ADN y su historia evolutiva.',['Uno de ellos es Protozoa.','El otro incluye las diatomeas.']);
mc('5','Con los tres dominios y cinco reinos, ¿en qué dominios queda el reino Monera?',['En Bacteria y en Archaea','Solo en Eukarya','Solo en Bacteria','En ninguno'],0,'Monera reúne a todas las procariotas, pero los dominios las separan en Bacteria y Archaea: por eso Monera queda repartido entre dos dominios.',['Monera reúne a todos los seres sin núcleo.','Hay dos dominios de procariotas.'],1);
mc('67','En el dominio Eukarya quedan los reinos:',['Los que tienen células con núcleo','Solo los animales','Las bacterias y arqueas','Solo las plantas'],0,'Eukarya reúne a todos los seres con núcleo: los protistas (o Protozoa y Chromista), los hongos, las plantas y los animales.',['Eu- significa verdadero y karyon, núcleo.','Incluye hongos, plantas y animales.'],1);
B.push({t:'reinos',k:'esc',m:'6',q:'Escribe el nombre del reino de las procariotas con pared de peptidoglucano en el modelo de seis reinos.',a:['eubacteria','eubacterias','reino eubacteria'],exp:'En el modelo de seis reinos, las procariotas con peptidoglucano forman el reino Eubacteria, y las arqueas el reino Archaebacteria.',p:['Significa «bacterias verdaderas».','Empieza por «Eu».']});
B.push({t:'reinos',k:'esc',m:'7',q:'Escribe el nombre del reino de la ameba y el tripanosoma en el modelo de siete reinos.',a:['protozoa','protozoos','reino protozoa'],exp:'En el modelo de siete reinos, la ameba, la euglena y el tripanosoma forman el reino Protozoa.',p:['Significa «primeros animales».','Empieza por «Proto».']});
B.push({t:'reinos',k:'vf',m:'67',q:'En este modelo, las eubacterias y las arqueas están en reinos distintos.',a:true,exp:'Verdadero. En los modelos de seis y siete reinos, el antiguo Monera se divide en dos reinos porque arqueas y eubacterias tienen pared, membrana y genes muy distintos.'});
var C=window.BIO_CLASIF;
if(C)for(var i=B.length-1;i>=0;i--){var q=B[i];if(q.t==='reinos'&&(!C.vale(q.m)||!C.valeD(q.d)))B.splice(i,1);}
})();
