/* ── Preguntas por DBA (versión 2.57): 24 para cada DBA con contenido nuevo ──
   9.6 ancestro común y evidencias (Evolución), 10.4 biotecnología (Genética) y
   11.5 país megadiverso y amenazas (Colombia, Ambiente). Llevan `dba` (DBA del MEN),
   `curso` (6 a 11, lo usa el filtro del panel docente) y `niv` (nivel del juego). */
(function(){
var L=[];
function M(t,dba,curso,niv,q,ops,p,exp){L.push({t:t,k:'mc',q:q,ops:ops,a:0,p:p,exp:exp,dba:dba,curso:curso,niv:niv});}
function V(t,dba,curso,niv,q,a,p,exp){L.push({t:t,k:'vf',q:q,a:a,p:p,exp:exp,dba:dba,curso:curso,niv:niv});}
/* ── DBA 9.6 · Evolución: teoría del ancestro común y sus evidencias ── */
var E='evolucion';
M(E,'9.6',9,2,'¿Qué propone la teoría del ancestro común?',['Todos los seres vivos descienden de antepasados compartidos','Cada especie fue creada por separado','Los humanos descienden del chimpancé actual','Las especies nunca cambian'],['Habla de parentesco entre todas las especies.','En el árbol de la vida, las ramas se unen en antepasados.'],'La teoría del ancestro común dice que todas las especies descienden de antepasados compartidos: si seguimos dos linajes hacia el pasado, llegan a un punto donde se unen.');
M(E,'9.6',9,2,'¿Qué es un ancestro común?',['Un antepasado compartido por dos o más especies','La especie más antigua que existe hoy','El primer ser humano','Un fósil de dinosaurio'],['Es un punto donde se unen dos ramas del árbol.','No es una especie viva hoy: ya se extinguió.'],'Un ancestro común es un antepasado del que descienden dos o más especies. Por ejemplo, el ser humano y el chimpancé comparten uno que vivió hace unos 7 millones de años.');
M(E,'9.6',9,2,'La aleta de una ballena y el brazo humano tienen los mismos huesos. Son órganos:',['Homólogos','Análogos','Vestigiales','Embrionarios'],['Se parecen en estructura aunque sirvan para cosas distintas.','Los heredaron de un antepasado común.'],'Los órganos homólogos tienen el mismo origen evolutivo y la misma estructura básica, aunque cumplan funciones distintas. Son evidencia de un ancestro común.');
M(E,'9.6',9,2,'El ala de un ave y la de una mariposa son órganos:',['Análogos','Homólogos','Vestigiales','Embrionarios'],['Las dos sirven para volar.','Pero la mariposa ni siquiera tiene huesos.'],'Los órganos análogos cumplen la misma función pero tienen distinto origen: el ala de la mariposa y la del ave no tienen la misma estructura ni un ancestro común reciente.');
M(E,'9.6',9,2,'El coxis humano, resto de una cola, es un órgano:',['Vestigial','Análogo','Nuevo','Embrionario'],['Es un resto de algo que tuvieron los antepasados.','Casi no cumple su función original.'],'Los órganos vestigiales están reducidos y casi sin uso: son huellas de estructuras que sí tenían nuestros antepasados, como la cola.');
M(E,'9.6',9,2,'Archaeopteryx tiene plumas y también dientes y cola larga. Es un fósil:',['De transición','De ambiente','De ADN','Actual'],['Muestra rasgos de dos grupos distintos.','Une a los dinosaurios con las aves.'],'Un fósil de transición muestra rasgos de un grupo antiguo y de uno nuevo. Archaeopteryx tiene plumas como un ave y dientes y cola como un dinosaurio.');
M(E,'9.6',9,2,'Cuanto más parecido es el ADN de dos especies, más…',['cercano es su ancestro común','lejano es su ancestro común','distinto es su hábitat','grande es su cuerpo'],['Piensa en cuánto tiempo hubo para acumular mutaciones.','Poco tiempo separadas, pocas diferencias.'],'Las mutaciones se acumulan con el tiempo. Si dos especies casi no difieren, se separaron hace poco: su ancestro común es reciente.');
M(E,'9.6',9,2,'¿Con cuál de estos organismos se parece más el ADN humano?',['Chimpancé','Gato','Pollo','Levadura'],['Es un primate africano.','Compartimos un ancestro común hace unos 7 millones de años.'],'El chimpancé es el pariente vivo más cercano del ser humano: sus secuencias de ADN y de proteínas son las más parecidas a las nuestras.');
M(E,'9.6',9,2,'En el citocromo c, el humano y el chimpancé tienen:',['Ninguna diferencia','Unas 10 diferencias','Unas 44 diferencias','Todos los aminoácidos distintos'],['Es una proteína de 104 aminoácidos.','Son parientes muy cercanos.'],'La secuencia del citocromo c es idéntica en el ser humano y el chimpancé. Con el perro hay unas 10 diferencias y con la levadura unas 44.');
M(E,'9.6',9,2,'¿Qué rasgo comparten los embriones de peces y humanos?',['Hendiduras en la garganta','Aletas','Escamas','Branquias funcionales'],['Se ven en las primeras semanas.','En los peces se vuelven branquias.'],'Los embriones de peces, reptiles, aves y mamíferos tienen hendiduras en la garganta y cola. En los peces forman las branquias y en nosotros, parte del oído y del cuello.');
M(E,'9.6',9,2,'¿Qué estudia la biogeografía?',['Dónde vive cada especie','Los huesos de los fósiles','La forma de las células','La velocidad de las mutaciones'],['«Geo» significa Tierra.','Estudia la distribución de las especies.'],'La biogeografía estudia dónde vive cada especie y por qué. Sus patrones apoyan la idea de ancestros comunes y de especies que se separaron.');
M(E,'9.6',9,2,'Los marsupiales viven en Australia y en América. Se explica porque:',['Tienen un ancestro común y los continentes estuvieron unidos','Cruzaron el océano nadando','Cada continente creó los suyos','Los trajo el viento'],['La Tierra no siempre tuvo los continentes como hoy.','Piensa en un antepasado compartido.'],'Los marsupiales descienden de un ancestro común que vivió cuando América del Sur, la Antártida y Australia estaban unidas. Al separarse los continentes, cada grupo evolucionó por su lado.');
M(E,'9.6',9,2,'Las especies de las islas Galápagos se parecen más a las de:',['Sudamérica','África','Australia','Europa'],['Las islas están frente a Ecuador.','Sus ancestros llegaron desde el continente cercano.'],'Darwin vio que las especies de Galápagos se parecen a las de Sudamérica, no a las de otras islas lejanas con clima parecido: descienden de especies del continente.');
M(E,'9.6',9,2,'Una mutación que da ventaja para sobrevivir y reproducirse tiende a…',['volverse más común','desaparecer','ser imposible','mantenerse igual'],['Los que la tienen dejan más descendientes.','Es el mecanismo de la selección natural.'],'Los individuos con una variante ventajosa sobreviven y se reproducen más, así que esa variante se hace más común en la población con las generaciones.');
M(E,'9.6',9,2,'¿De dónde sale la variación que usa la selección natural?',['De las mutaciones y la recombinación','Del uso y el desuso','Del deseo del organismo','Del ambiente que cambia el ADN'],['Aparece al azar, antes de la selección.','Se mezcla en la reproducción sexual.'],'La variación aparece por mutaciones al azar y se mezcla por recombinación. El ambiente no la produce: solo «escoge» las variantes que ya existen.');
M(E,'9.6',9,2,'Las capas profundas de roca tienen fósiles…',['más antiguos','más recientes','iguales a los actuales','de la misma edad que las superiores'],['Las capas nuevas se depositan encima.','Lo de abajo se formó primero.'],'En las rocas sedimentarias las capas más profundas son las más antiguas, así que sus fósiles también lo son.');
M(E,'9.6',9,2,'¿Cuál es una prueba molecular de parentesco?',['Comparar secuencias de ADN','Medir el tamaño del cuerpo','Contar las patas','Observar el color'],['Se usan genes y proteínas.','Se hace con secuenciadores.'],'Al comparar secuencias de ADN o de proteínas se mide cuánto cambiaron dos especies desde su ancestro común: es una prueba molecular de parentesco.');
M(E,'9.6',9,2,'¿En qué orden aparecen las eras geológicas?',['Paleozoica, Mesozoica, Cenozoica','Cenozoica, Mesozoica, Paleozoica','Mesozoica, Paleozoica, Cenozoica','Cenozoica, Paleozoica, Mesozoica'],['De la más antigua a la más reciente.','Los dinosaurios van en la del medio.'],'De la más antigua a la más reciente: Paleozoica (peces, anfibios), Mesozoica (dinosaurios) y Cenozoica (mamíferos). Vivimos en la Cenozoica.');
V(E,'9.6',9,2,'Los humanos descendemos de los chimpancés actuales.',false,['Piensa en un antepasado compartido.','Los dos linajes se separaron hace unos 7 millones de años.'],'Falso. Humanos y chimpancés compartimos un ancestro común que vivió hace unos 7 millones de años; ninguno desciende del otro.');
V(E,'9.6',9,2,'Dos especies emparentadas solo pueden vivir en el mismo lugar.',false,['Piensa en los marsupiales de Australia y América.','Los continentes se movieron.'],'Falso. Especies emparentadas pueden vivir en continentes distintos si sus ancestros se separaron al moverse los continentes.');
V(E,'9.6',9,2,'Los órganos homólogos tienen el mismo origen evolutivo.',true,['Piensa en el brazo y la aleta.','Comparten estructura heredada.'],'Verdadero. Los homólogos derivan de una estructura del ancestro común, aunque hoy cumplan funciones distintas.');
V(E,'9.6',9,2,'Un órgano análogo prueba que dos especies comparten un ancestro común reciente.',false,['Compara función con origen.','Las alas de ave y mariposa son análogas.'],'Falso. Los órganos análogos solo comparten la función. Lo que apoya el parentesco son los homólogos.');
V(E,'9.6',9,2,'Las mutaciones aparecen porque el organismo las necesita.',false,['Ocurren al azar.','El ambiente solo selecciona, no las provoca.'],'Falso. Las mutaciones son azarosas: no aparecen «porque se necesitan». La selección natural actúa después sobre las que ya existen.');
V(E,'9.6',9,2,'La selección natural actúa sobre la variación que ya existe en una población.',true,['Primero hay variantes.','Luego el ambiente favorece a unas.'],'Verdadero. Sin variación no hay selección: el ambiente favorece a las variantes que ya existen en la población.');
/* ── DBA 10.4 · Genética: biotecnología y sus implicaciones ── */
var G='genetica';
M(G,'10.4',10,3,'¿Qué es la biotecnología?',['Usar seres vivos o sus moléculas para producir algo útil','Estudiar solo los virus','Construir máquinas con metal','Observar células al microscopio'],['Hacer yogur o pan ya lo es.','Hoy incluye cortar y pegar genes.'],'La biotecnología usa seres vivos, células o moléculas para obtener productos o servicios: desde el pan y el yogur hasta los medicamentos con ADN recombinante.');
M(G,'10.4',10,3,'¿Qué es un organismo transgénico?',['Uno con un gen de otra especie','Uno criado en laboratorio','Uno sin genes','Uno sin ADN'],['«Trans» quiere decir «a través de».','Se le inserta un gen de afuera.'],'Un organismo transgénico lleva un gen de otra especie, insertado con técnicas de ADN recombinante. Ejemplos: el maíz Bt y las bacterias que fabrican insulina humana.');
M(G,'10.4',10,3,'La insulina para la diabetes se produce hoy en:',['Bacterias con el gen humano','Páncreas de vaca','Plantas de maíz','Hongos del suelo'],['Se usa ADN recombinante.','Las bacterias se multiplican muy rápido.'],'Se inserta el gen humano de la insulina en bacterias, que la fabrican en grandes cantidades. Es más barato y seguro que extraerla de animales.');
M(G,'10.4',10,3,'El maíz Bt resiste plagas porque lleva un gen de:',['Una bacteria','Un virus humano','Un hongo comestible','Un pez'],['La proteína Bt afecta a ciertos insectos.','Viene de Bacillus thuringiensis.'],'El maíz Bt lleva un gen de la bacteria Bacillus thuringiensis, que produce una proteína tóxica para ciertas larvas de insectos.');
M(G,'10.4',10,3,'La oveja Dolly se obtuvo por:',['Clonación por transferencia de núcleo','Fecundación in vitro','Terapia génica','Cruce selectivo'],['Nació en 1996.','Se pasó el núcleo de una célula adulta a un óvulo sin núcleo.'],'Dolly se obtuvo pasando el núcleo de una célula de oveja adulta a un óvulo sin núcleo: es una clonación por transferencia nuclear.');
M(G,'10.4',10,3,'La clonación terapéutica busca producir:',['Tejidos para trasplantes','Individuos completos','Plantas nuevas','Virus'],['No busca un nuevo individuo.','Se piensa en reemplazar tejidos dañados.'],'La clonación terapéutica busca obtener tejidos u órganos compatibles con un paciente. La reproductiva busca un individuo completo.');
M(G,'10.4',10,3,'La clonación reproductiva busca obtener:',['Un individuo con el mismo ADN nuclear','Un tejido para trasplantes','Una proteína nueva','Un cruce de especies'],['Como Dolly.','Copia a un individuo existente.'],'La clonación reproductiva produce un individuo con el mismo ADN nuclear del donante del núcleo. Plantea dilemas éticos y técnicos.');
M(G,'10.4',10,3,'CRISPR se describe como:',['Unas tijeras moleculares para editar el ADN','Un microscopio','Una vacuna','Un fertilizante'],['Corta en un lugar preciso.','Permite corregir un gen.'],'CRISPR-Cas9 permite cortar el ADN en un sitio exacto y así eliminar, corregir o insertar un gen.');
M(G,'10.4',10,3,'¿Qué es la terapia génica?',['Corregir o reemplazar un gen defectuoso','Clonar a un paciente','Fecundar un óvulo en el laboratorio','Cambiar el sexo de un embrión'],['Se aplica a personas enfermas.','Actúa sobre el gen que causa la enfermedad.'],'La terapia génica introduce una copia funcional de un gen, o lo corrige, en las células de un paciente con una enfermedad hereditaria.');
M(G,'10.4',10,3,'La fecundación in vitro une óvulo y espermatozoide…',['En el laboratorio','En el útero','En la trompa de Falopio','En el ovario'],['«In vitro» significa «en vidrio».','Después se implanta el embrión.'],'En la fecundación in vitro la unión ocurre fuera del cuerpo, en el laboratorio, y luego el embrión se implanta en el útero.');
M(G,'10.4',10,3,'¿Qué pregunta es de bioética?',['¿Es correcto hacerlo?','¿Qué enzima se usa?','¿Cuánto cuesta?','¿Cuánto demora?'],['No pregunta cómo, sino si debe hacerse.','Habla de lo que es justo y respetuoso.'],'La bioética analiza si es correcto hacer algo con la vida, no solo si es posible: consentimiento, dignidad, justicia y privacidad.');
M(G,'10.4',10,3,'En Colombia, ¿quién decide qué cultivos modificados se siembran?',['El ICA','El DANE','La NASA','El Icfes'],['Es una entidad agropecuaria.','Sigue el Protocolo de Cartagena.'],'El Instituto Colombiano Agropecuario (ICA), junto con otras entidades, evalúa los riesgos y autoriza los organismos modificados, siguiendo el Protocolo de Cartagena sobre bioseguridad.');
M(G,'10.4',10,3,'¿Qué riesgo ambiental se discute de los transgénicos?',['Cruce con variedades nativas','Que dejen de tener ADN','Que no necesiten agua','Que se vuelvan animales'],['Se piensa en el polen.','Afecta a las variedades de la región.'],'Un riesgo discutido es que el polen de un cultivo transgénico fecunde variedades nativas y las altere, con efectos en la biodiversidad y en las comunidades.');
M(G,'10.4',10,3,'Una prueba de ADN en medicina legal sirve para:',['Identificar personas','Medir la estatura','Contar bacterias','Fabricar insulina'],['Compara regiones muy variables.','Se usa con víctimas y desaparecidos.'],'Se comparan regiones del ADN que varían mucho entre personas, así se identifican víctimas y desaparecidos y se resuelven casos de paternidad.');
M(G,'10.4',10,3,'El Proyecto Genoma Humano buscó:',['Descifrar la secuencia de bases del ADN humano','Clonar a una persona','Fabricar insulina','Curar el cáncer en un año'],['Terminó hacia 2003.','Leyó unos 3 000 millones de pares de bases.'],'El Proyecto Genoma Humano secuenció casi todo el ADN humano y mostró dónde están nuestros genes y cómo varían entre personas.');
M(G,'10.4',10,3,'Una ventaja del maíz Bt resistente a plagas es:',['Menos plaguicidas','Más ADN','Crece sin agua','No necesita sol'],['Evita fumigar tanto.','Beneficia al agricultor y al ambiente.'],'Como la planta se protege sola de ciertas plagas, el agricultor necesita aplicar menos insecticida, siempre que las plagas no se vuelvan resistentes.');
M(G,'10.4',10,3,'Una enzima de restricción sirve para:',['Cortar el ADN en sitios específicos','Copiar el ADN completo','Unir aminoácidos','Fabricar ARN'],['Es una «tijera» natural de las bacterias.','Reconoce secuencias concretas.'],'Las enzimas de restricción cortan el ADN en secuencias específicas; con otra enzima, la ligasa, se unen fragmentos y se arma ADN recombinante.');
M(G,'10.4',10,3,'¿Qué dilema plantea guardar datos genéticos?',['La privacidad','El color del ADN','El tamaño del tubo','La temperatura de la sala'],['Tu ADN dice mucho sobre ti.','Podría usarlo un seguro o un empleador.'],'El ADN revela información muy personal, así que surge la pregunta de quién la guarda, quién puede usarla y si puede discriminarte (seguros, empleo).');
V(G,'10.4',10,3,'Hacer yogur con bacterias es un tipo de biotecnología.',true,['Usa seres vivos para obtener un producto.','Es una de las más antiguas.'],'Verdadero. La biotecnología incluye procesos tradicionales (pan, yogur, queso) y modernos (ADN recombinante).');
V(G,'10.4',10,3,'La clonación terapéutica crea un individuo completo.',false,['Busca tejidos.','La reproductiva sí busca un individuo.'],'Falso. La clonación terapéutica busca producir tejidos u órganos; la reproductiva busca un individuo completo.');
V(G,'10.4',10,3,'Un organismo transgénico tiene genes de otra especie.',true,['Es la definición.','Se insertan con ADN recombinante.'],'Verdadero. Un transgénico lleva uno o más genes de otra especie insertados mediante técnicas de ingeniería genética.');
V(G,'10.4',10,3,'La terapia génica se usa ya para algunas enfermedades hereditarias.',true,['Hay tratamientos aprobados.','Aún es muy costosa.'],'Verdadero. Existen terapias génicas aprobadas para ciertas enfermedades hereditarias, aunque son muy costosas y plantean dilemas de acceso.');
V(G,'10.4',10,3,'Editar el ADN con CRISPR no plantea dilemas éticos.',false,['Piensa en editar embriones.','También pesa quién puede pagarlo.'],'Falso. CRISPR plantea dilemas bioéticos (editar embriones), sociales (acceso y costo) y ambientales (modificar organismos).');
V(G,'10.4',10,3,'El núcleo de un clon tiene el mismo ADN del individuo del que se tomó.',true,['Se copió el núcleo de una célula.','Por eso Dolly se parecía a su donante.'],'Verdadero. El ADN del núcleo del clon es idéntico al del donante; solo el ADN mitocondrial viene del óvulo receptor.');
/* ── DBA 11.5 · Colombia y ambiente: país megadiverso y sus amenazas ── */
var C='colombia',A='ambiente';
M(C,'11.5',11,3,'¿Qué significa que un país sea megadiverso?',['Tiene gran parte de las especies del mundo','Es el país más grande','Tiene más habitantes','No tiene especies en peligro'],['«Mega» quiere decir muy grande.','Se refiere a la cantidad de especies.'],'Un país megadiverso reúne una proporción muy alta de las especies del planeta. Colombia es uno de ellos aunque ocupa menos del 1 % de la Tierra.');
M(C,'11.5',11,3,'Colombia es el primer país del mundo en especies de:',['Aves','Mamíferos','Reptiles','Peces de mar'],['Más de 1 900 especies.','Incluye colibríes y tangaras.'],'Colombia tiene la mayor diversidad de aves del mundo (más de 1 900 especies); también es el primero en orquídeas y mariposas.');
M(C,'11.5',11,3,'Colombia ocupa el primer lugar mundial en especies de:',['Orquídeas','Coníferas','Cactus','Ballenas'],['Son plantas de flores muy vistosas.','La flor nacional es una de ellas.'],'Colombia es el país con más especies de orquídeas (más de 4 200). Su flor nacional, la Cattleya trianae, es una orquídea.');
M(C,'11.5',11,3,'Una especie endémica es la que:',['Solo vive en un lugar del mundo','Vive en todos los continentes','Viene de otro país','Está en todos los ecosistemas'],['«Endémico» viene de «propio de un lugar».','Si desaparece de allí, desaparece del planeta.'],'Una especie endémica solo existe en una región. Colombia tiene muchas, por ejemplo varios frailejones y ranas de los Andes.');
M(C,'11.5',11,3,'La minería ilegal de oro contamina los ríos con:',['Mercurio','Calcio','Oxígeno','Sodio'],['Es un metal líquido.','Se acumula en los peces.'],'En la minería ilegal se usa mercurio para separar el oro; cae a los ríos, se acumula en los peces y llega a las personas que los comen.');
M(C,'11.5',11,3,'Una causa de deforestación en la Amazonía colombiana es:',['Ampliar potreros para ganado','Sembrar árboles nativos','Crear parques naturales','Reciclar papel'],['Se tala para sembrar pasto.','Es una actividad agropecuaria.'],'Gran parte de la deforestación amazónica se debe a convertir bosque en pastos para ganadería extensiva, además de cultivos ilícitos, minería ilegal y apertura de vías.');
M(C,'11.5',11,3,'¿Qué efecto tienen las carreteras en la fauna?',['Fragmentan su hábitat','Aumentan su hábitat','Protegen a los animales','Producen alimento'],['Dividen el bosque.','Los animales cruzan y pueden morir.'],'Las carreteras fragmentan el hábitat: separan poblaciones, causan atropellos y facilitan que lleguen colonizadores y tala.');
M(C,'11.5',11,3,'Un corredor biológico es:',['Una franja de bosque que conecta áreas','Una carretera para fauna','Una zona de minería','Un cultivo de maíz'],['Conecta zonas protegidas.','Permite el paso de los animales.'],'Un corredor biológico une áreas aisladas para que los animales y las plantas se muevan, se crucen y mantengan su variabilidad genética.');
M(C,'11.5',11,3,'Un sistema silvopastoril combina:',['Pastos y árboles','Minería y ganado','Maíz y plaguicidas','Solo cultivos'],['«Silvo» viene de bosque.','Los árboles dan sombra al ganado.'],'En un sistema silvopastoril se siembran árboles junto con los pastos: mejora el suelo, da sombra y reduce la presión sobre el bosque.');
M(C,'11.5',11,3,'Los páramos son importantes porque:',['Almacenan y regulan agua','Producen petróleo','Tienen mucho oro','Son desiertos'],['Se parecen a esponjas.','De ahí vienen muchos acueductos.'],'Los frailejones y el suelo del páramo captan la neblina y la lluvia y la liberan poco a poco, abasteciendo de agua a muchas ciudades.');
M(C,'11.5',11,3,'El tráfico de fauna consiste en:',['Capturar y vender animales silvestres','Criar animales en una finca','Rescatar animales heridos','Vacunar a la fauna'],['Es ilegal.','Los animales a menudo mueren en el transporte.'],'El tráfico de fauna es la captura y venta ilegal de animales silvestres como mascotas o adornos; reduce las poblaciones en la naturaleza.');
M(C,'11.5',11,3,'Si ves vender fauna silvestre, lo mejor es:',['Denunciar ante la autoridad ambiental','Comprar el animal para salvarlo','Ignorarlo','Soltarlo en cualquier parque'],['Comprar mantiene el negocio.','Hay autoridades que atienden estos casos.'],'Comprar animales alimenta el tráfico. Lo correcto es denunciar a la autoridad ambiental para que rescate y devuelva los animales a su hábitat.');
M(C,'11.5',11,3,'El derretimiento de los nevados afecta a la biodiversidad porque:',['Cambia el agua y los hábitats de alta montaña','Aumenta el desierto','Reduce el nivel del mar','Enfría los páramos'],['Los glaciares alimentan humedales y ríos.','Las especies de altura no tienen a dónde subir.'],'Los nevados aportan agua a los páramos y ríos. Al retroceder, cambian los hábitats y las especies de alta montaña pueden quedarse sin lugar donde vivir.');
M(A,'11.5',11,3,'Un bosque presta el servicio ecosistémico de:',['Regular el agua y el clima','Producir plástico','Generar petróleo','Fabricar mercurio'],['Beneficios de la naturaleza para las personas.','Incluye agua, clima y suelos.'],'Los servicios ecosistémicos son los beneficios que la naturaleza da a las personas. Un bosque regula el agua, almacena carbono y protege el suelo.');
M(A,'11.5',11,3,'¿Qué agrava el calentamiento global?',['La quema de combustibles fósiles','La siembra de árboles','Los parques naturales','El reciclaje'],['Libera dióxido de carbono.','Se usan en transporte e industria.'],'La quema de carbón, petróleo y gas libera CO₂ y otros gases de efecto invernadero que retienen calor en la atmósfera.');
M(A,'11.5',11,3,'¿Qué acción ayuda a frenar la deforestación?',['Proteger y restaurar bosques','Talar para sembrar pasto','Quemar la maleza','Abrir más carreteras'],['Es lo contrario de talar.','Se siembran especies nativas.'],'Proteger los bosques, restaurar con especies nativas y comprar productos con certificado de origen ayudan a reducir la deforestación.');
M(A,'11.5',11,3,'¿Cómo se llama analizar un problema ambiental desde lo económico, social, ambiental y cultural?',['Visión sistémica','Visión parcial','Visión única','Visión local'],['Mira todo el sistema.','Une varios puntos de vista.'],'Una visión sistémica considera que lo ambiental, lo económico, lo social y lo cultural están conectados, y evalúa las decisiones con todos ellos.');
M(C,'11.5',11,3,'La ganadería extensiva sobre suelos de bosque tiende a:',['Compactar y erosionar el suelo','Aumentar la biodiversidad','Fijar más carbono','Aumentar los polinizadores'],['El peso del ganado y la falta de árboles pesan.','Sin raíces, la lluvia arrastra el suelo.'],'Al talar el bosque y dejar solo pasto, el pisoteo del ganado compacta el suelo y, sin cobertura de raíces, la lluvia lo erosiona.');
V(C,'11.5',11,3,'Colombia es uno de los países megadiversos del mundo.',true,['Es primero en aves y orquídeas.','Tiene muchas especies para su tamaño.'],'Verdadero. Colombia está entre los países megadiversos, con una enorme riqueza de especies y ecosistemas.');
V(C,'11.5',11,3,'La deforestación solo afecta a los árboles.',false,['Piensa en los animales que viven allí.','También se erosiona el suelo y cambia el agua.'],'Falso. Talar el bosque destruye el hábitat de miles de especies, aumenta la erosión y cambia el ciclo del agua y el clima.');
V(C,'11.5',11,3,'Las comunidades locales pueden ser buenas guardianas de los bosques.',true,['Viven en el territorio.','Conocen sus plantas y animales.'],'Verdadero. Cuando participan y se benefician, las comunidades indígenas, afrodescendientes y campesinas son de las mejores guardianas de los ecosistemas.');
V(C,'11.5',11,3,'Los monocultivos aumentan la biodiversidad del suelo.',false,['Es una sola especie sembrada.','Se aplican muchos agroquímicos.'],'Falso. Los monocultivos y los agroquímicos empobrecen el suelo y reducen la variedad de organismos, incluidos los polinizadores.');
V(C,'11.5',11,3,'El tráfico de fauna silvestre no afecta a las poblaciones en la naturaleza.',false,['Cada animal capturado sale del ecosistema.','Muchos mueren en el transporte.'],'Falso. Capturar animales silvestres disminuye sus poblaciones y puede llevar a especies al borde de la extinción.');
V(C,'11.5',11,3,'Proteger un ecosistema completo protege a muchas especies a la vez.',true,['Todas comparten el mismo hábitat.','Una sola especie depende de muchas otras.'],'Verdadero. Un área protegida cuida el alimento, el agua y el refugio de cientos de especies al mismo tiempo.');
BIO_NUEVAS(L);
})();
/* ── DBA 7.4 (versión 2.58): ciclos del carbono, el nitrógeno y el agua; intervención humana ── */
(function(){
var L=[];
function M(t,q,ops,p,exp){L.push({t:t,k:'mc',q:q,ops:ops,a:0,p:p,exp:exp,dba:'7.4',curso:7,niv:1});}
function V(t,q,a,p,exp){L.push({t:t,k:'vf',q:q,a:a,p:p,exp:exp,dba:'7.4',curso:7,niv:1});}
var E='ecosistemas',A='ambiente';
M(E,'¿Qué hacen las bacterias fijadoras de nitrógeno?',['Fijan el nitrógeno del aire en el suelo','Producen oxígeno','Hacen fotosíntesis','Eliminan el nitrógeno'],['Viven en las raíces de algunas plantas.','Convierten el gas del aire en una forma útil.'],'Las bacterias fijadoras convierten el nitrógeno del aire (N₂) en compuestos que las plantas pueden absorber, y así abren el ciclo del nitrógeno.');
M(E,'¿Qué gas es el más abundante del aire y forma parte del ciclo del nitrógeno?',['Nitrógeno','Oxígeno','Argón','Hidrógeno'],['Ocupa cerca de las tres cuartas partes del aire.','No es el que respiramos.'],'El aire es casi 78 % nitrógeno (N₂), pero la mayoría de los seres vivos no puede usarlo directamente: necesitan que otros organismos lo fijen.');
M(E,'¿Cómo vuelve el agua de las plantas a la atmósfera?',['Por transpiración','Por sedimentación','Por fijación','Por fermentación'],['Sale por los estomas de las hojas.','Es como «sudar» de la planta.'],'Las plantas absorben agua por las raíces y la liberan como vapor por las hojas: es la transpiración, parte del ciclo del agua.');
M(E,'¿Qué proceso pasa el agua de líquido a gas por el calor del Sol?',['Evaporación','Condensación','Precipitación','Infiltración'],['Ocurre en mares, ríos y lagos.','El gas sube a la atmósfera.'],'La evaporación convierte el agua líquida en vapor gracias a la energía del Sol; luego se condensa y vuelve como lluvia.');
M(E,'¿Qué efecto tiene talar un bosque sobre el ciclo del agua?',['Reduce la humedad y la lluvia de la zona','Aumenta la transpiración','Fabrica más agua','No cambia nada'],['Sin árboles hay menos vapor de agua.','El suelo también retiene menos agua.'],'Sin árboles disminuyen la transpiración y la humedad, y el suelo desnudo retiene menos agua: las lluvias locales se alteran y aumentan las inundaciones.');
M(A,'¿Qué es la erosión del suelo?',['Desgaste y arrastre del suelo','Formación de rocas nuevas','Aumento de la lluvia','Crecimiento de las raíces'],['Se lleva la capa fértil.','La lluvia y el viento son sus agentes.'],'La erosión es el desgaste y arrastre del suelo por el agua o el viento. La deforestación la acelera porque ya no hay raíces que lo sujeten.');
M(A,'¿Qué causa la eutrofización de un lago?',['Exceso de nutrientes como nitratos y fosfatos','Falta de nutrientes','Exceso de oxígeno','Más peces'],['Llegan fertilizantes de los cultivos.','Las algas crecen sin control.'],'El exceso de nitratos y fosfatos hace que las algas se multipliquen; al morir, su descomposición gasta el oxígeno y mueren los peces.');
M(E,'¿Qué organismos devuelven nutrientes al suelo al descomponer la materia muerta?',['Hongos y bacterias','Productores','Consumidores primarios','Depredadores'],['Son los «recicladores» del ecosistema.','Actúan sobre hojas y animales muertos.'],'Los descomponedores (hongos y bacterias) transforman la materia muerta en nutrientes que las plantas vuelven a usar: cierran los ciclos de la materia.');
M(A,'¿Qué acción ayuda a usar el agua de forma responsable en casa?',['Cerrar la llave al cepillarse','Dejar el grifo abierto','Lavar el carro todos los días','Regar con manguera al mediodía'],['Es una acción pequeña y diaria.','Evita desperdiciar agua potable.'],'Cerrar la llave mientras no se usa, arreglar las fugas y reutilizar el agua son acciones que reducen el consumo y protegen las fuentes de agua.');
M(E,'¿Qué cultivo ayuda a dejar nitrógeno aprovechable en el suelo?',['Leguminosas como el fríjol','Papa','Maíz','Café'],['Sus raíces tienen nódulos con bacterias.','Se siembran para abonar el suelo.'],'Las leguminosas viven en simbiosis con bacterias fijadoras de nitrógeno, así que enriquecen el suelo y reducen la necesidad de fertilizantes.');
M(E,'¿Cómo pasa el carbono del CO₂ del aire a los seres vivos?',['Por la fotosíntesis','Por la respiración','Por la fermentación','Por la erosión'],['Lo hacen los productores.','Usan luz, agua y CO₂.'],'Las plantas, algas y algunas bacterias fijan el carbono del CO₂ en glucosa durante la fotosíntesis; de ahí pasa a toda la cadena trófica.');
M(A,'¿Qué actividad humana aumenta el CO₂ de la atmósfera?',['Quemar combustibles fósiles','Sembrar árboles','Reciclar papel','Ahorrar agua'],['Libera carbono guardado hace millones de años.','Se hace en motores e industrias.'],'Al quemar petróleo, carbón y gas se libera a la atmósfera carbono que estaba almacenado bajo tierra, lo que desequilibra el ciclo del carbono.');
V(E,'El agua se recicla continuamente en el ciclo del agua.',true,['Se evapora, se condensa y vuelve como lluvia.','No se «gasta» en el planeta.'],'Verdadero. El agua cambia de estado y de lugar, pero se conserva: lo que se contamina o se agota es el agua dulce utilizable.');
V(E,'La mayoría de las plantas puede usar directamente el nitrógeno del aire.',false,['Necesitan formas como nitratos o amonio.','Las bacterias fijadoras lo transforman.'],'Falso. El N₂ del aire es muy poco reactivo: las plantas absorben nitratos y amonio, que producen las bacterias.');
V(A,'La deforestación no afecta los ciclos del carbono ni del agua.',false,['Los árboles guardan carbono.','También devuelven agua a la atmósfera.'],'Falso. Talar libera el carbono almacenado, reduce la transpiración y aumenta la erosión: altera ambos ciclos.');
BIO_NUEVAS(L);
})();
/* ── DBA 9.5 (versión 2.58): expresión del ADN, fenotipo y mutaciones ── */
(function(){
var L=[];
function M(q,ops,p,exp){L.push({t:'genetica',k:'mc',q:q,ops:ops,a:0,p:p,exp:exp,dba:'9.5',curso:9,niv:2});}
function V(q,a,p,exp){L.push({t:'genetica',k:'vf',q:q,a:a,p:p,exp:exp,dba:'9.5',curso:9,niv:2});}
M('¿Qué codón le indica al ribosoma que termine la traducción?',['UAA','AUG','GCU','CCU'],['Es un codón de parada.','No codifica ningún aminoácido.'],'UAA, UAG y UGA son codones de parada: no tienen ARNt y el ribosoma suelta la cadena de aminoácidos.');
M('Una mutación cambia una base del ADN. ¿Qué puede cambiar?',['Un aminoácido de la proteína','El número de cromosomas','La especie del organismo','El color del ADN'],['Piensa en lo que codifica el gen.','Un cambio en el gen puede cambiar la proteína.'],'Un cambio de base puede cambiar un codón y, con él, un aminoácido; la proteína puede plegarse o funcionar distinto y cambiar el fenotipo.');
M('El genotipo es:',['El conjunto de genes de un individuo','El aspecto visible del individuo','El ambiente donde vive','El número de hijos'],['Habla de la información del ADN.','El fenotipo es lo que se ve.'],'El genotipo es la información genética (los alelos que tiene); el fenotipo es la característica observable que resulta de ella y del ambiente.');
M('¿Qué molécula lleva la copia del gen hasta el ribosoma?',['ARN mensajero','ADN polimerasa','ARN de transferencia','Lípido'],['Se forma en la transcripción.','Sale del núcleo.'],'El ARN mensajero copia el gen en el núcleo y viaja al citoplasma, donde el ribosoma lo traduce a proteína.');
M('¿Por qué distintos codones pueden dar el mismo aminoácido?',['El código genético es degenerado','El ARN es muy corto','Los ribosomas se equivocan','Las proteínas no tienen aminoácidos'],['Hay 64 codones y 20 aminoácidos.','Algunos aminoácidos tienen varios codones.'],'Con 64 codones para 20 aminoácidos, casi todos los aminoácidos tienen más de un codón: algunas mutaciones no cambian la proteína.');
M('La anemia falciforme se debe a:',['Un cambio de una base en el gen de la hemoglobina','Un virus en la sangre','Una falta de hierro en la dieta','Un exceso de glóbulos blancos'],['Es hereditaria.','Cambia un aminoácido de la hemoglobina.'],'Un solo cambio de base en el gen de la hemoglobina cambia un aminoácido; los glóbulos rojos adoptan forma de hoz y transportan peor el oxígeno.');
V('Todas las mutaciones cambian la proteína y el fenotipo.',false,['Piensa en el código degenerado.','Algunas mutaciones no tienen efecto.'],'Falso. Muchas mutaciones no cambian el aminoácido o ocurren en regiones sin función, y no afectan al fenotipo.');
V('El ambiente puede influir en el fenotipo sin cambiar el genotipo.',true,['Piensa en el color de la piel con el sol.','El ADN permanece igual.'],'Verdadero. El fenotipo resulta del genotipo y del ambiente: por ejemplo, la estatura depende de los genes y de la alimentación.');
BIO_NUEVAS(L);
})();
